// Zero-combat RPC fixture. The engine has no fight entrypoint here.
#include "stagea.h"
#include "candidates.h"
#include <iostream>
#include <iomanip>
int main(){std::string line;std::cout<<std::setprecision(17);while(std::getline(std::cin,line)){try{auto request=js::parse(line);js::V out;auto row=js::get(request,"candidateFrame");if(row.tag!=js::V::Undefined){stageb2::Frame f;f.width=js::num(js::get(row,"width"));f.height=js::num(js::get(row,"height"));auto matrix=[](js::V v){std::vector<stageb2::Row> m;for(auto a:v.p->items){stageb2::Row r;for(auto x:a.p->items)r.push_back(js::num(x));m.push_back(r);}return m;};f.units=matrix(js::get(row,"units"));f.own=matrix(js::get(row,"own"));f.shells=matrix(js::get(row,"shells"));f.shots=matrix(js::get(row,"shots"));f.fields=matrix(js::get(row,"fields"));f.casts=matrix(js::get(row,"casts"));auto lv=js::get(row,"longVelocity");if(lv.tag!=js::V::Undefined)for(auto k:js::keys(lv)){auto v=js::get(lv,k);f.longVelocity[unsigned(std::stoul(js::str(k)))]={js::num(v.p->items[0]),js::num(v.p->items[1])};}auto bank=stageb2::candidates(f,unsigned(js::num(js::get(request,"id"))));auto serialize=[](const std::vector<stageb2::Candidate>& cs){js::Args rows;for(auto& c:cs){js::Args features;for(auto v:c.features)features.push_back(v);rows.push_back(js::obj({{"point",js::arr({c.point.x,c.point.y})},{"features",js::arr(std::move(features))},{"type",double(c.type)},{"source",double(c.source)}}));}return js::arr(std::move(rows));};out=js::obj({{"aim",serialize(bank.aim)},{"move",serialize(bank.move)},{"combat_steps",0}});}else out=stagea::replay(request);std::cout<<js::stringify(out)<<'\n';}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}}
